struct Row {
    dialect: &'static str,
    case: usize,
    stride: &'static str,
    code: i32,
    result: &'static str,
    kind: &'static str,
    resident: bool,
    stream_sha256: &'static str,
}
fn unhex(text: &str) -> Vec<u8> {
    text.as_bytes()
        .as_chunks::<2>()
        .0
        .iter()
        .map(|pair| {
            let text = core::str::from_utf8(pair).unwrap();
            u8::from_str_radix(text, 16).unwrap()
        })
        .collect()
}
